import json
import math
import matplotlib.pyplot as plt


# Read results generated by runner.py
with open("results.json", "r") as f:
    results = json.load(f)


# -----------------------------
# Collect data
# -----------------------------

capacity_sums = []

bfs_b = []
bfs_d = []
bfs_time = []

dfs_b = []
dfs_D = []
dfs_time = []


for case in results:
    capacities = [int(c) for c in case["capacities"]]
    capacity_sum = sum(capacities)

    capacity_sums.append(capacity_sum)

    # BFS
    bfs_b.append(case["bfs"]["branching_factor"])

    if case["bfs"]["solution_depth"] is None:
        bfs_d.append(math.nan)
    else:
        bfs_d.append(case["bfs"]["solution_depth"])

    bfs_time.append(case["bfs"]["execution_time"])

    # DFS
    dfs_b.append(case["dfs"]["branching_factor"])
    dfs_D.append(case["dfs"]["max_depth"])
    dfs_time.append(case["dfs"]["execution_time"])


# -----------------------------
# BFS Plot
# -----------------------------

fig, ax1 = plt.subplots()

ax1.plot(
    capacity_sums,
    bfs_b,
    marker="o",
    label="Branching Factor (b)"
)

ax1.plot(
    capacity_sums,
    bfs_d,
    marker="o",
    label="Solution Depth (d)"
)

ax1.set_xlabel("Sum of Capacities")
ax1.set_ylabel("Branching Factor / Depth")
ax1.set_title("BFS Scaling Behavior")
ax1.legend(loc="upper left")


# Secondary y-axis for execution time
ax2 = ax1.twinx()

ax2.plot(
    capacity_sums,
    bfs_time,
    marker="o",
    linestyle="--",
    label="Execution Time"
)

ax2.set_ylabel("Execution Time (seconds)")
ax2.legend(loc="upper right")

plt.tight_layout()
plt.savefig("bfs_plot.png")
plt.show()


# -----------------------------
# DFS Plot
# -----------------------------

fig, ax1 = plt.subplots()

ax1.plot(
    capacity_sums,
    dfs_b,
    marker="o",
    label="Branching Factor (b)"
)

ax1.plot(
    capacity_sums,
    dfs_D,
    marker="o",
    label="Maximum Depth (D)"
)

ax1.set_xlabel("Sum of Capacities")
ax1.set_ylabel("Branching Factor / Depth")
ax1.set_title("DFS Scaling Behavior")
ax1.legend(loc="upper left")


# Secondary y-axis for execution time
ax2 = ax1.twinx()

ax2.plot(
    capacity_sums,
    dfs_time,
    marker="o",
    linestyle="--",
    label="Execution Time"
)

ax2.set_ylabel("Execution Time (seconds)")
ax2.legend(loc="upper right")

plt.tight_layout()
plt.savefig("dfs_plot.png")
plt.show()